1	import 'package:json_annotation/json_annotation.dart';
2	
3	import '../../../../core/failure/failure.dart';
4	import '../../domain/entities/export_job_state.dart';
5	
6	part 'export_job_status_dto.g.dart';
7	
8	/// `export.status.get`'s own response `data` (`openapi.yaml:1495-1539`) —
9	/// decodes every field the contract declares, even [narrativeErrorCode]/
10	/// [downloadAvailable] which this story never reads (both belong to
11	/// Story 7.2's download wiring) — kept here so the DTO always mirrors the
12	/// full contract shape, not just today's consumer.
13	@JsonSerializable()
14	class ExportJobStatusDto {
15	  const ExportJobStatusDto({
16	    required this.jobId,
17	    required this.status,
18	    required this.narrativeStatus,
19	    required this.entryCount,
20	    required this.errorCode,
21	    required this.narrativeErrorCode,
22	    required this.downloadAvailable,
23	  });
24	
25	  final String jobId;
26	  final String status;
27	  final String narrativeStatus;
28	  final int? entryCount;
29	  final String? errorCode;
30	  final String? narrativeErrorCode;
31	  final bool downloadAvailable;
32	
33	  factory ExportJobStatusDto.fromJson(Map<String, dynamic> json) =>
34	      _$ExportJobStatusDtoFromJson(json);
35	
36	  Map<String, dynamic> toJson() => _$ExportJobStatusDtoToJson(this);
37	
38	  /// `docs/input/backend/export-screen-states.md`'s own status×
39	  /// narrativeStatus×downloadAvailable mapping table, implemented once
40	  /// here — `ExportRepositoryImpl.getStatus`'s own "thin pass-through"
41	  /// (Code Map) calls straight through to this method, with no mapping
42	  /// logic of its own.
43	  ///
44	  /// AD-3 ("reuse the existing `Failure.exportEmptyPeriod`... never add a
45	  /// new `Failure` subtype") is honored by going through the one shared
46	  /// [Failure.fromCode] for every `status: 'error'` response and then
47	  /// branching on the *subtype* it returns, rather than re-testing the
48	  /// literal `'EXPORT_EMPTY_PERIOD'` string a second time here — this
49	  /// stays correct even if a future taxonomy edit ever changed which code
50	  /// means "empty period", with no second place to update.
51	  ExportJobState toState() {
52	    switch (status) {
53	      case 'pending':
54	        return const ExportJobState.preparing();
55	      case 'processing':
56	      case 'data_ready':
57	        // Design Notes — `data_ready` folds into `generating`'s own
58	        // visual here, no case of its own (lighting it up is Story
59	        // 7.2's job).
60	        return const ExportJobState.generating();
61	      case 'done':
62	        return ExportJobState.done(
63	          narrativeStatus == 'done'
64	              ? ExportOutcome.narrativeReady
65	              : ExportOutcome.narrativeUnavailable,
66	        );
67	      case 'error':
68	        final failure = Failure.fromCode(
69	          errorCode ?? '',
70	          'Não foi possível gerar a exportação.',
71	        );
72	        return failure is ExportEmptyPeriod
73	            ? const ExportJobState.emptyPeriod()
74	            : ExportJobState.error(failure);
75	      default:
76	        // Forward-compatible: an unrecognized `status` (shouldn't happen —
77	        // the contract's own enum is closed) never crashes the poll loop
78	        // (RNF09) — surfaces as a terminal error instead.
79	        return ExportJobState.error(
80	          Failure.malformedResponse(message: 'Unknown export status: $status'),
81	        );
82	    }
83	  }
84	}
