1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	
5	import '../../domain/entities/export_job_state.dart';
6	import '../../domain/repositories/export_repository.dart';
7	
8	/// Drives `ExportStatusSheet` (spec-7-1) — a fresh, `get_it`-factory-
9	/// scoped instance per download-icon tap (Code Map: the `registerFactory`
10	/// one-shot-cubit precedent set by `TextEntryCubit`), closed by the call
11	/// site itself once done with it (`MeusRegistrosScreen`'s own export handler/
12	/// `ExportStatusSheet.show()`, mirroring `InsertionModal.show()`'s own
13	/// cubit-disposal convention), never by a `get_it` `dispose:` hook.
14	///
15	/// Starts in [ExportJobState.preparing] — the same visual the
16	/// `export-summary-create` 202 response's own `status: 'pending'` always
17	/// implies (`openapi.yaml`), so no separate "creating..." state is needed
18	/// before [start]'s own `createJob` call resolves.
19	class ExportJobCubit extends Cubit<ExportJobState> {
20	  ExportJobCubit(this._repository) : super(const ExportJobState.preparing());
21	
22	  final ExportRepository _repository;
23	
24	  /// Design Notes — fixed poll cadence (docs/input is silent on this):
25	  /// the server job always reaches a terminal state, so no client
26	  /// timeout exists either.
27	  static const _pollInterval = Duration(seconds: 2);
28	
29	  /// Review finding (blind-hunter/edge-case-hunter layers) — a persistent
30	  /// `getStatus` failure (as opposed to one flaky blip) would otherwise
31	  /// poll forever with the sheet stuck on its last state and no visible
32	  /// indication anything is wrong. After this many *consecutive* failures,
33	  /// [_poll] gives up and surfaces the existing generic [ExportJobError]
34	  /// state instead — reusing the sheet's own already-built error visual
35	  /// rather than inventing a new one.
36	  static const _maxConsecutivePollFailures = 5;
37	
38	  String? _jobId;
39	  Timer? _pollTimer;
40	  int _consecutivePollFailures = 0;
41	
42	  /// Review finding (blind-hunter/edge-case-hunter layers) — `Timer.
43	  /// periodic` doesn't wait for one tick's own `_poll()` to finish before
44	  /// firing the next; without this guard, a `getStatus` call slower than
45	  /// [_pollInterval] could race a second, overlapping call, and a late,
46	  /// stale response landing after a newer terminal state was already
47	  /// emitted could "un-terminate" an already-finished job in the UI.
48	  bool _pollInFlight = false;
49	
50	  /// Creates the export job for [periodStart]/[periodEnd]
51	  /// (`export-summary-create`) and, on success, starts this cubit's own
52	  /// `Timer.periodic` poll loop against `export-status-get`.
53	  ///
54	  /// Returns `false` on a create failure (Boundaries: "Create fails →
55	  /// inline error, sheet never opens") — the same failure is also
56	  /// emitted as [ExportJobState.error] so the caller can read [state] for
57	  /// [Failure.message] without this method also having to hand back the
58	  /// raw `Failure` itself (the `Either<Failure, T>` shape, RNF09, is the
59	  /// repository's own contract, not every cubit method's).
60	  Future<bool> start({
61	    required DateTime periodStart,
62	    required DateTime periodEnd,
63	  }) async {
64	    final result = await _repository.createJob(
65	      periodStart: periodStart,
66	      periodEnd: periodEnd,
67	    );
68	    if (isClosed) {
69	      return false;
70	    }
71	    return result.match(
72	      (failure) {
73	        emit(ExportJobState.error(failure));
74	        return false;
75	      },
76	      (jobId) {
77	        _jobId = jobId;
78	        _startPolling();
79	        return true;
80	      },
81	    );
82	  }
83	
84	  void _startPolling() {
85	    _pollTimer?.cancel();
86	    _pollTimer = Timer.periodic(_pollInterval, (_) => _poll());
87	  }
88	
89	  Future<void> _poll() async {
90	    final jobId = _jobId;
91	    if (jobId == null || _pollInFlight || _isTerminal(state)) {
92	      return;
93	    }
94	    _pollInFlight = true;
95	    try {
96	      final result = await _repository.getStatus(jobId);
97	      if (isClosed || _isTerminal(state)) {
98	        return;
99	      }
100	      result.match(
101	        (failure) {
102	          // A transient poll failure (docs/input is silent on this) is
103	          // swallowed rather than surfaced, so one flaky network blip
104	          // never flips a still-running job to a false terminal error —
105	          // the next tick simply tries again. A *persistent* one gives up
106	          // after [_maxConsecutivePollFailures] instead of polling
107	          // forever.
108	          _consecutivePollFailures++;
109	          if (_consecutivePollFailures >= _maxConsecutivePollFailures) {
110	            _pollTimer?.cancel();
111	            emit(ExportJobState.error(failure));
112	          }
113	        },
114	        (newState) {
115	          _consecutivePollFailures = 0;
116	          emit(newState);
117	          if (_isTerminal(newState)) {
118	            _pollTimer?.cancel();
119	          }
120	        },
121	      );
122	    } finally {
123	      _pollInFlight = false;
124	    }
125	  }
126	
127	  bool _isTerminal(ExportJobState state) =>
128	      state is ExportJobDone ||
129	      state is ExportJobError ||
130	      state is ExportJobEmptyPeriod;
131	
132	  @override
133	  Future<void> close() {
134	    _pollTimer?.cancel();
135	    return super.close();
136	  }
137	}
