8	/// Registers the `export` feature into the project's single `get_it`
9	/// instance (`sl`) — mirrors `capture_injection.dart`'s own shape.
10	/// [ExportJobCubit] is a `registerFactory`, not a `lazySingleton` (Code
11	/// Map: "`registerFactory<TextEntryCubit>` one-shot-cubit precedent") — a
12	/// fresh instance per download-icon tap, closed by the call site itself
13	/// once its sheet is gone (`ExportStatusSheet.show()`), never by a
14	/// `get_it` `dispose:` hook. No Hive box here (AD-15: export jobs are
15	/// never persisted locally).
16	void registerExportFeature() {
17	  sl.registerLazySingleton<ExportRemoteDataSource>(
18	    () => ExportRemoteDataSource(sl<ApiClient>()),
19	  );
20	
21	  sl.registerLazySingleton<ExportRepository>(
22	    () => ExportRepositoryImpl(remoteDataSource: sl<ExportRemoteDataSource>()),
23	  );
24	
25	  sl.registerFactory<ExportJobCubit>(
26	    () => ExportJobCubit(sl<ExportRepository>()),
27	  );
28	}
