1	import 'package:fpdart/fpdart.dart';
2	
3	import '../../../../core/failure/failure.dart';
4	import '../../../../core/network/api_client.dart';
5	import '../models/export_job_status_dto.dart';
6	
7	/// The export feature's one remote data source — `export-summary-create`/
8	/// `export-status-get`, called by `x-cerne-function` name only
9	/// (AGENTS.md), [jobId] appended as [getStatus]'s one trailing path
10	/// segment. Mirrors `ChatRemoteDataSource`'s own try/catch-to-
11	/// `malformedResponse` shape for every decode step (RNF09).
12	class ExportRemoteDataSource {
13	  ExportRemoteDataSource(this._apiClient);
14	
15	  final ApiClient _apiClient;
16	
17	  /// `includeNarrative` is left unset — its own `openapi.yaml` default is
18	  /// `true`, and docs/input gives this story no reason to ever request a
19	  /// narrative-less export.
20	  ///
21	  /// Review finding (blind-hunter layer): [periodStart]/[periodEnd] arrive
22	  /// from `showDateRangePicker` as local-midnight `DateTime`s for the
23	  /// first/last *day* the user picked — sending [periodEnd] as-is (local
24	  /// midnight) would silently exclude every entry made later that same day
25	  /// from the export. Rebuilt here to the full local calendar day
26	  /// (start-of-day..end-of-day) before the one `.toUtc()` conversion, so
27	  /// the day boundary the user actually saw is preserved regardless of
28	  /// device timezone.
29	  Future<Either<Failure, String>> createJob({
30	    required DateTime periodStart,
31	    required DateTime periodEnd,
32	  }) async {
33	    final startOfDay = DateTime(
34	      periodStart.year,
35	      periodStart.month,
36	      periodStart.day,
37	    );
38	    final endOfDay = DateTime(
39	      periodEnd.year,
40	      periodEnd.month,
41	      periodEnd.day,
42	      23,
43	      59,
44	      59,
45	      999,
46	    );
47	    final result = await _apiClient.post(
48	      'export-summary-create',
49	      data: {
50	        'periodStart': startOfDay.toUtc().toIso8601String(),
51	        'periodEnd': endOfDay.toUtc().toIso8601String(),
52	      },
53	    );
54	    return result.flatMap((json) {
55	      try {
56	        final data = json['data'] as Map<String, dynamic>;
57	        return right(data['jobId'] as String);
58	      } catch (error) {
59	        return left(Failure.malformedResponse(message: error.toString()));
60	      }
61	    });
62	  }
63	
64	  Future<Either<Failure, ExportJobStatusDto>> getStatus(String jobId) async {
65	    final result = await _apiClient.get(
66	      'export-status-get',
67	      pathParams: [jobId],
68	    );
69	    return result.flatMap((json) {
70	      try {
71	        final data = json['data'] as Map<String, dynamic>;
72	        return right(ExportJobStatusDto.fromJson(data));
73	      } catch (error) {
74	        return left(Failure.malformedResponse(message: error.toString()));
75	      }
76	    });
77	  }
78	}
