12	/// A controllable fake (same hand-written convention `ChatCubit`'s own
13	/// test suite uses for `ChatRepository`) rather than a mocktail stub —
14	/// [getStatusResults] is a queue consumed one entry per `getStatus` call,
15	/// repeating its last entry once exhausted, so a test only has to queue
16	/// the few stages it cares about.
17	class _FakeExportRepository implements ExportRepository {
18	  Either<Failure, String> createJobResult = right('job-1');
19	  final List<({DateTime periodStart, DateTime periodEnd})> createJobCalls = [];
20	
21	  final List<Either<Failure, ExportJobState>> getStatusResults = [];
22	  final List<String> getStatusCalls = [];
23	
24	  /// Review finding (verification-gap layer) — when set, the next
25	  /// `getStatus` call doesn't resolve until this completer completes,
26	  /// letting a test hold one poll tick's own repository call open across
27	  /// a second (and third) `Timer.periodic` tick firing underneath it —
28	  /// the exact overlap `ExportJobCubit._pollInFlight` exists to prevent.
29	  /// Consumed once, then cleared, so only the call it was set for waits.
30	  Completer<void>? delayNextGetStatus;
31	
32	  @override
33	  Future<Either<Failure, String>> createJob({
34	    required DateTime periodStart,
35	    required DateTime periodEnd,
36	  }) async {
37	    createJobCalls.add((periodStart: periodStart, periodEnd: periodEnd));
38	    return createJobResult;
39	  }
40	
41	  @override
42	  Future<Either<Failure, ExportJobState>> getStatus(String jobId) async {
43	    // Recorded before the gate below so a test can observe "the call was
44	    // made and is still in flight" — not just "the call has resolved".
45	    getStatusCalls.add(jobId);
46	    final gate = delayNextGetStatus;
47	    delayNextGetStatus = null;
48	    if (gate != null) {
49	      await gate.future;
50	    }
51	    if (getStatusResults.isEmpty) {
52	      return right(const ExportJobState.generating());
53	    }
54	    final index = (getStatusCalls.length - 1).clamp(
55	      0,
56	      getStatusResults.length - 1,
57	    );
58	    return getStatusResults[index];
59	  }
60	}
