/// "Baixar PDF" — see [_download].
Future<void> downloadPdf() => _download(ExportDownloadFormat.pdf);

/// "Baixar dados brutos" — see [_download].
Future<void> downloadRawData() => _download(ExportDownloadFormat.raw);

/// Resolves [format]'s signed download URL (`export-download-get`) and
/// hands it to [_downloadOpener] to open externally — never buffered in
/// this app (Boundaries). [lastDownloadFailure] is reset to `null` up
/// front and left that way on success, so a caller that reads it right
/// after `await`ing this method sees only *this* attempt's own outcome,
/// never a stale failure from an earlier, unrelated tap.
Future<void> _download(ExportDownloadFormat format) async {
  lastDownloadFailure = null;
  final jobId = _jobId;
  if (jobId == null) {
    return;
  }
  final result = await _repository.getDownloadUrl(jobId, format: format);
  if (isClosed) {
    return;
  }
  lastDownloadFailure = await result.match(
    (failure) async => failure,
    (url) async {
      final opened = await _downloadOpener.open(url);
      return opened
          ? null
          : const Failure.malformedResponse(
              message: 'Não foi possível abrir o arquivo.',
            );
    },
  );
}

