/// `ExportJobDone`'s own two flavors (I/O matrix's "Concluído" vs.
/// "Narrativa falhou/pulada" rows) — spec-7-2: both buttons now wired to a
/// real download via [_handleDownload], never `onPressed: null`.
List<Widget> _doneContent(
  BuildContext context,
  ExportJobCubit cubit,
  ExportOutcome outcome,
) {
  if (outcome == ExportOutcome.narrativeReady) {
    return [
      const Icon(
        Icons.check_circle,
        size: DesignTokens.exportStatusIconSize,
        color: DesignTokens.colorSuccess,
      ),
      const SizedBox(height: DesignTokens.exportStatusContentGap),
      const _StatusText('Resumo pronto'),
      const SizedBox(height: DesignTokens.exportStatusContentGap),
      Row(
        children: [
          Expanded(
            child: AppButton(
              label: 'Baixar PDF',
              onPressed: () =>
                  _handleDownload(context, cubit, cubit.downloadPdf),
            ),
          ),
          const SizedBox(width: DesignTokens.exportStatusButtonGap),
          Expanded(
            child: AppButton(
              label: 'Baixar dados brutos',
              variant: AppButtonVariant.secondaryOutline,
              onPressed: () =>
                  _handleDownload(context, cubit, cubit.downloadRawData),
            ),
          ),
        ],
      ),
    ];
  }
  return [
    const Icon(
      Icons.error_outline,
      size: DesignTokens.exportStatusIconSize,
      color: DesignTokens.colorError,
    ),
    const SizedBox(height: DesignTokens.exportStatusContentGap),
    const _StatusText(
      'Não foi possível gerar o resumo — a narrativa falhou, mas seus '
      'dados continuam disponíveis.',
      color: DesignTokens.colorError,
    ),
    const SizedBox(height: DesignTokens.exportStatusContentGap),
    AppButton(
      label: 'Baixar dados brutos',
      variant: AppButtonVariant.secondaryOutline,
      onPressed: () => _handleDownload(context, cubit, cubit.downloadRawData),
    ),
  ];
}

/// Routes a download-button tap through [cubit]'s own [download] method
/// (`downloadPdf`/`downloadRawData`), then surfaces
/// `ExportJobCubit.lastDownloadFailure` — if the attempt left one behind —
/// as an inline `SnackBar`, mirroring `_onExportTap`'s own create-failure
/// pattern (`meus_registros_screen.dart`). Never touches [state]/rebuilds
/// the sheet's own job-status content (Boundaries) — the failure is read
/// off, and cleared from, the cubit's plain field, not folded into
/// [ExportJobState].
Future<void> _handleDownload(
  BuildContext context,
  ExportJobCubit cubit,
  Future<void> Function() download,
) async {
  await download();
  final failure = cubit.lastDownloadFailure;
  if (failure == null) {
    return;
  }
  cubit.lastDownloadFailure = null;
  if (!context.mounted) {
    return;
  }
  ScaffoldMessenger.of(
    context,
  ).showSnackBar(SnackBar(content: Text(failure.message)));
}

