group('spec-7-2 — getRedirectLocation', () {
  test(
    'a 302 with a Location header -> Right(that URL), never auto-'
    'followed (followRedirects: false means dio hands the 302 straight '
    'back rather than chasing it into the signed-storage host)',
    () async {
      final response = Response<dynamic>(
        requestOptions: requestOptions,
        statusCode: 302,
        headers: Headers.fromMap({
          'location': ['https://storage.example.com/signed'],
        }),
      );
      when(
        () => mockDio.get<dynamic>(
          any(),
          queryParameters: any(named: 'queryParameters'),
          options: any(named: 'options'),
        ),
      ).thenAnswer((_) async => response);

      final result = await apiClient.getRedirectLocation(
        'export-download-get',
        pathParams: ['job-1'],
        queryParameters: {'format': 'pdf'},
      );

      expect(result.isRight(), isTrue);
      result.match(
        (_) => fail('expected Right'),
        (url) => expect(url, 'https://storage.example.com/signed'),
      );

      final captured = verify(
        () => mockDio.get<dynamic>(
          captureAny(),
          queryParameters: captureAny(named: 'queryParameters'),
          options: any(named: 'options'),
        ),
      ).captured;
      expect(captured[0], '$baseUrl/export-download-get/job-1');
      expect(captured[1], {'format': 'pdf'});
    },
  );

  test(
    'a response with no Location header -> Left(MalformedResponse) '
    '(I/O matrix: "Missing Location")',
    () async {
      final response = Response<dynamic>(
        requestOptions: requestOptions,
        statusCode: 302,
        headers: Headers(),
      );
      when(
        () => mockDio.get<dynamic>(
          any(),
          queryParameters: any(named: 'queryParameters'),
          options: any(named: 'options'),
        ),
      ).thenAnswer((_) async => response);

      final result = await apiClient.getRedirectLocation(
        'export-download-get',
        pathParams: ['job-1'],
      );

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<MalformedResponse>()),
        (_) => fail('expected Left'),
      );
    },
  );

  test(
    'an error response (e.g. NOT_FOUND) still maps through the same '
    '_mapDioException path every other method uses — the permissive '
    'validateStatus only widens what counts as success, never changes '
    'how a real error status is mapped',
    () async {
      final dioError = DioException(
        requestOptions: requestOptions,
        response: Response(
          requestOptions: requestOptions,
          statusCode: 404,
          data: {
            'code': 'NOT_FOUND',
            'message': 'Job not found',
            'retryable': false,
          },
        ),
        type: DioExceptionType.badResponse,
      );
      when(
        () => mockDio.get<dynamic>(
          any(),
          queryParameters: any(named: 'queryParameters'),
          options: any(named: 'options'),
        ),
      ).thenThrow(dioError);

      final result = await apiClient.getRedirectLocation(
        'export-download-get',
        pathParams: ['job-1'],
      );

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<NotFound>()),
        (_) => fail('expected Left'),
      );
    },
  );

  test(
    'a non-DioException thrown by dio -> Left(MalformedResponse), never '
    'a crash',
    () async {
      when(
        () => mockDio.get<dynamic>(
          any(),
          queryParameters: any(named: 'queryParameters'),
          options: any(named: 'options'),
        ),
      ).thenThrow(StateError('unexpected native failure'));

      final result = await apiClient.getRedirectLocation(
        'export-download-get',
        pathParams: ['job-1'],
      );

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<MalformedResponse>()),
        (_) => fail('expected Left'),
      );
    },
  );
});

