358	    expect((cubit.state as ExportJobError).failure, isA<RateLimited>());
359	    // Exactly one request ever left — RATE_LIMITED is one of the 6
360	    // retryable codes (RetryInterceptor.retryableCodes), so without the
361	    // neverRetriedFunctions exclusion this would be 1 + maxRetries.
362	    expect(adapter.requests, hasLength(1));
363	
364	    // No poll ever starts for a job that was never created.
365	    await Future<void>.delayed(const Duration(seconds: 3));
366	    expect(
367	      adapter.requests.every((r) => !r.path.contains('export-status-get')),
368	      isTrue,
369	    );
370	  });
371	}
